ALTER TABLE "restro"."payments" ADD COLUMN "receipt_to_bring_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD COLUMN "receipt_brought_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD COLUMN "receipt_brought_by" text;--> statement-breakpoint
CREATE INDEX "payments_receipt_open_idx" ON "restro"."payments" USING btree ("venue_id","service_date") WHERE "restro"."payments"."receipt_to_bring_at" is not null and "restro"."payments"."receipt_brought_at" is null;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD CONSTRAINT "payments_receipt_brought" CHECK (("restro"."payments"."receipt_brought_at" is null) = ("restro"."payments"."receipt_brought_by" is null) and ("restro"."payments"."receipt_brought_at" is null or "restro"."payments"."receipt_to_bring_at" is not null) and ("restro"."payments"."receipt_brought_by" is null or "restro"."payments"."receipt_brought_by" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$') and ("restro"."payments"."receipt_to_bring_at" is null or "restro"."payments"."state" = 'captured'));